  Deno.test(`mlKemRawPrivateNotSupported:${variant.name}`, async () => {
    // raw-private is not a spec format for ML-KEM (only raw-seed/pkcs8/jwk).
    const kp = await subtleAny.generateKey(
      { name: variant.name },
